18	// addControlPlaneFlags registers the persistent flags shared by every
19	// control-plane command group. Persistent so they're inherited by nested
20	// subcommands (e.g. `entire repo mirror list`):
21	//   - --json: emit the raw wire JSON instead of the default human table.
22	//   - --insecure-http-auth: permit the token exchange over plain http://
23	//     (local/dev deployments where the core isn't behind TLS). Hidden, as
24	//     elsewhere in the CLI.
25	func addControlPlaneFlags(cmd *cobra.Command) {
26		cmd.PersistentFlags().Bool("json", false, "output raw JSON instead of a table")
27		cmd.PersistentFlags().Bool("insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
28		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
29			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
30		}
31	}
32	
33	// jsonRequested reports whether --json was set on cmd or an ancestor. A
34	// lookup error means the flag isn't defined on this command tree, which is
35	// treated as "not requested".
36	func jsonRequested(cmd *cobra.Command) bool {
37		v, err := cmd.Flags().GetBool("json")
38		return err == nil && v
39	}
40	
41	// insecureHTTPRequested reports whether --insecure-http-auth was set on cmd
42	// or an ancestor.
43	func insecureHTTPRequested(cmd *cobra.Command) bool {
44		v, err := cmd.Flags().GetBool("insecure-http-auth")
45		return err == nil && v
46	}
